SELECT t.assignment_id, t.level_2_full_code, t.nama_usaha_dicari, t.nama_usaha, t.nama_usaha_edit, t.assignment_status_alias, t.keberadaan_usaha_label, t.nama_usaha_sim, t.nama_usaha_edit_sim FROM (SELECT DISTINCT a.assignment_id, a.level_2_full_code, 'CITRA OKU MEDIA , PT' AS nama_usaha_dicari, nama_usaha, nama_usaha_edit, a.assignment_status_alias, keberadaan_usaha_label, ngram_search(nama_usaha, 'CITRA OKU MEDIA , PT', 2) AS nama_usaha_sim, ngram_search(nama_usaha_edit, 'CITRA OKU MEDIA , PT', 2) AS nama_usaha_edit_sim FROM tgr_fd68e454.base_table_assignment a JOIN tgr_fd68e454.root_table b ON (a.assignment_id = b.assignment_id AND a.assignment_date_modified = b.assignment_date_modified) JOIN tgr_fd68e454.se2026_nested c ON (a.assignment_id = c.assignment_id AND a.assignment_date_modified = c.assignment_date_modified) JOIN tgr_fd68e454.USAHA_REF d ON (a.assignment_id = d.assignment_id AND a.assignment_date_modified = d.assignment_date_modified) WHERE a.is_active = 1 AND a.level_2_full_code = '1601' AND (ngram_search(nama_usaha, 'CITRA OKU MEDIA , PT', 2) >= 0.8 OR ngram_search(nama_usaha_edit, 'CITRA OKU MEDIA , PT', 2) >= 0.8) UNION ALL SELECT DISTINCT a.assignment_id, a.level_2_full_code, 'CITRA OKU MEDIA , PT' AS nama_usaha_dicari, nama_usaha, '-' AS nama_usaha_edit, a.assignment_status_alias, keberadaan_label, ngram_search(nama_usaha, 'CITRA OKU MEDIA , PT', 2) AS nama_usaha_sim, '-' AS nama_usaha_edit_sim FROM tcz_37526b20.base_table_assignment a JOIN tcz_37526b20.root_table b ON (a.assignment_id = b.assignment_id AND a.assignment_date_modified = b.assignment_date_modified) WHERE a.is_active = 1 AND a.level_2_full_code = '1601' AND ngram_search(nama_usaha, 'CITRA OKU MEDIA , PT', 2) >= 0.8) t ORDER BY GREATEST(nama_usaha_sim, CASE WHEN nama_usaha_edit_sim = '-' THEN nama_usaha_sim ELSE nama_usaha_edit_sim END) DESC LIMIT 1
